insert into public.announcements
  (id, organization_id, title, content, audience, status, published_at)
values
  ('aa000000-0000-4000-8000-000000000001', 'aaaa0000-0000-4000-8000-000000000001', 'Welcome to the new HRMS platform', 'We have launched the new GrowthifyEdge HRMS. All employee records, documents and organization settings now live in one place. Please review your profile details.', 'all', 'published', '2026-08-01T09:00:00Z'),
  ('aa000000-0000-4000-8000-000000000002', 'aaaa0000-0000-4000-8000-000000000001', 'Q3 all-hands meeting', 'Our quarterly all-hands takes place on Friday, August 21 at 4:00 PM PKT. The agenda covers Q2 results, Q3 goals and new team introductions.', 'all', 'published', '2026-07-28T10:30:00Z'),
  ('aa000000-0000-4000-8000-000000000003', 'aaaa0000-0000-4000-8000-000000000001', 'Updated leave policy', 'The updated leave policy takes effect September 1. Annual leave accrual moves to a monthly schedule; carry-over rules stay unchanged. Details are in the policy handbook.', 'all', 'published', '2026-07-15T08:00:00Z'),
  ('aa000000-0000-4000-8000-000000000004', 'aaaa0000-0000-4000-8000-000000000001', 'Two new engineers joining this month', 'Please welcome Hana Yamamoto and Omar Sheikh, who join the Engineering team in July. Say hello when you see them in the directory.', 'all', 'published', '2026-07-08T11:00:00Z')
on conflict (id) do nothing;

